\subsection{Definitions and mathematical statement}
\paragraph{Shared notation.}$\mathbb N$, $\mathbb Z$, $\mathbb Q$, $\mathbb R$, and $\mathbb C$ denote the natural numbers, integers, rationals, reals, and complex numbers, respectively. All additional parameters and hypotheses are specified in the question.


\paragraph{Statement recorded in the supplied source.}
For $\lambda\in(0,1)$, let $\mu_\lambda$ be the distribution of $\sum_{n\geq0}A_n\lambda^n$, where the $A_n$ are independent unbiased random variables taking values $\pm1$. Determine the set of parameters $\lambda$ for which $\mu_\lambda$ is absolutely continuous.
\par\smallskip\textit{Formulation references:} \href{https://huggingface.co/datasets/ulamai/UnsolvedMath}{[S1]}, \href{https://doi.org/10.4171/owr/2016/21}{[S2]}.

\subsection{Short English statement}
For $\lambda\in(0,1)$, let $\mu_\lambda$ be the distribution of $\sum_{n\geq0}A_n\lambda^n$, where the $A_n$ are independent unbiased random variables taking values $\pm1$. Determine the set of parameters $\lambda$ for which $\mu_\lambda$ is absolutely continuous.

\subsection{Sources}
\begin{itemize}
\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 30003113 (OWR-14603-012). Catalogue attribution under CC BY 4.0.
\url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
\item[S2] Original problem formulation and mathematical context.
\url{https://doi.org/10.4171/owr/2016/21}.
\end{itemize}
\label{end:30003113}

